import{_ as a,o,c as i,a6 as s}from"./chunks/framework.DNkVJs23.js";const m=JSON.parse('{"title":"Política de privacidad","description":"Política de privacidad — Sapphire Star Codex","frontmatter":{"description":"Política de privacidad — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/es-419/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/es-419/privacy/"}],["meta",{"property":"og:title","content":"Política de privacidad | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Política de privacidad — Sapphire Star Codex"}]]},"headers":[],"relativePath":"es-419/privacy/index.md","filePath":"es-419/privacy/index.md"}'),r={name:"es-419/privacy/index.md"};function n(t,e,c,l,d,p){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="politica-de-privacidad" tabindex="-1">Política de privacidad <a class="header-anchor" href="#politica-de-privacidad" aria-label="Permalink to &quot;Política de privacidad&quot;">​</a></h1><p>Vigente desde el 31 de octubre de 2026. Última actualización del texto original: 10 de noviembre de 2026. Traducción: 14 de noviembre de 2026.</p><p>Esta política se aplica a las apps iOS, Android y HarmonyOS de Sapphire Star Codex y a este sitio. Desarrollador: <strong>eurekaffeine (刘耀晨)</strong>. Contacto: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Las funciones varían según la plataforma; no hace falta una cuenta.</p><h2 id="datos-locales" tabindex="-1">Datos locales <a class="header-anchor" href="#datos-locales" aria-label="Permalink to &quot;Datos locales&quot;">​</a></h2><p>La app guarda en el dispositivo las preferencias de juego, idioma y apariencia, el historial de búsqueda y estado de navegación, los favoritos, sets y nombres guardados, e inventarios de decoraciones, talismanes y armaduras. Estos datos permiten usar las funciones y no se suben al desarrollador. El desarrollador no ofrece cuentas ni sincronización en la nube.</p><h2 id="permisos-y-recopilacion-automatica" tabindex="-1">Permisos y recopilación automática <a class="header-anchor" href="#permisos-y-recopilacion-automatica" aria-label="Permalink to &quot;Permisos y recopilación automática&quot;">​</a></h2><p>La app no integra SDK de anuncios, seguimiento, estadísticas de uso ni envío automático de informes de fallos. Sus funciones actuales no requieren contactos, ubicación, cámara, micrófono o fotos y no recopilan identificadores publicitarios. El sistema y las tiendas pueden tratar datos de instalación o diagnóstico según sus propias reglas. El desarrollador usa los diagnósticos que recibe de las plataformas únicamente para resolver problemas.</p><h2 id="contacto-y-servicios-externos" tabindex="-1">Contacto y servicios externos <a class="header-anchor" href="#contacto-y-servicios-externos" aria-label="Permalink to &quot;Contacto y servicios externos&quot;">​</a></h2><p>Al escribir voluntariamente por correo, el desarrollador recibe tu dirección, mensaje y archivos adjuntos para responder, investigar problemas y atender solicitudes de privacidad, no para marketing. Envía solo información necesaria. Gmail procesa el correo según la <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">política de Google</a>.</p><p>GitHub Pages aloja este sitio y puede recibir la dirección IP y datos técnicos del navegador; consulta la <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">declaración de GitHub</a>. No se añaden estadísticas de visitas, cookies publicitarias ni píxeles de seguimiento. La búsqueda se realiza en el navegador, que puede guardar preferencias. Los servicios externos tienen sus propias políticas y pueden tratar datos fuera de tu país.</p><h2 id="aportaciones-y-copias-de-seguridad" tabindex="-1">Aportaciones y copias de seguridad <a class="header-anchor" href="#aportaciones-y-copias-de-seguridad" aria-label="Permalink to &quot;Aportaciones y copias de seguridad&quot;">​</a></h2><p>Alipay o WeChat Pay procesa las aportaciones según sus condiciones. El sitio solo muestra códigos estáticos, sin SDK de pago ni recepción de credenciales. El desarrollador puede ver los datos que la plataforma muestra al destinatario, como importe, fecha, nombre visible y nota, para comprobar las aportaciones y resolver problemas. Se conservan según las reglas de la plataforma y las obligaciones aplicables. Según tus ajustes, los datos pueden incluirse en copias del dispositivo o de la nube; el desarrollador no puede leer ni borrar dichas copias.</p><h2 id="cesion-conservacion-y-eliminacion" tabindex="-1">Cesión, conservación y eliminación <a class="header-anchor" href="#cesion-conservacion-y-eliminacion" aria-label="Permalink to &quot;Cesión, conservación y eliminación&quot;">​</a></h2><p>El desarrollador no vende ni alquila datos personales ni los comparte para publicidad. El proveedor indicado procesa el correo. La información que el desarrollador posee puede entregarse por obligación legal o a petición expresa.</p><p>Elimina los datos locales mediante la app o los ajustes del sistema. Las desinstalaciones que conservan datos no los borran; gestiona aparte las copias de seguridad, que pueden restaurarlos. Las preferencias del sitio permanecen hasta que las borres o el navegador las limpie. Los mensajes se conservan solo para la gestión, el seguimiento o las obligaciones legales. Los proveedores gestionan sus propios registros y copias. Contacta para acceder, corregir o solicitar la eliminación de lo enviado, salvo obligaciones de conservación. El desarrollador no puede acceder a distancia a datos que solo estén en el dispositivo.</p><h2 id="seguridad-menores-y-cambios" tabindex="-1">Seguridad, menores y cambios <a class="header-anchor" href="#seguridad-menores-y-cambios" aria-label="Permalink to &quot;Seguridad, menores y cambios&quot;">​</a></h2><p>Los mecanismos del sistema protegen los datos locales. El sitio usa HTTPS. Solo se accede a los mensajes para asistencia y privacidad, con las protecciones del servicio de correo. La app no solicita perfiles personales ni fechas de nacimiento y no busca recopilar datos de menores. Los responsables de un menor pueden pedir que se borre información que haya enviado.</p><p>Esta política y su fecha cambian cuando cambian las prácticas. Los cambios importantes se anuncian en el sitio o en las actualizaciones de la app. Los permisos o consentimientos necesarios para nuevas funciones se solicitan por separado; esta política no los sustituye.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};
